    "unitId": "n2:task-comprehension:2018-12:3:line-4",
    "text": "そうですか。郵送での申請も受け付けていますが、事前にこちらに手数料等を振り込んでいただきます。申し込みの際、身分証明書の写しを同封してください。あるいは、窓口で代理の方に申し込んでいただくこともできます。その場合、ご本人との関係を確認するための書類が必要となります。",
