    "unitId": "n2:task-comprehension:2018-12:4:line-8",
    "text": "この研修会では新商品の企画書を書くところまでするだろ。うまくいけば、実際商品化されることもあるから、いい企画書書けるよう頑張って。いい経験になると思うから。",
